#include <print>
#include <cstdio>

class FileGuard {
public:
    explicit FileGuard(const char* path) : f_(std::fopen(path, "w")) {
        std::println("打开 {}", path);
    }
    ~FileGuard() {
        if (f_) std::fclose(f_);
        std::println("自动关闭");
    }
    void write(const char* s) { if (f_) std::fputs(s, f_); }
private:
    std::FILE* f_ = nullptr;
};

int main() {
    {
        FileGuard f("/tmp/raii_demo.txt");
        f.write("hello raii\n");
        std::println("提前走人的那条出口");
        return 0;
    }
    std::println("已离开作用域");
    return 0;
}
// 照样关：return 0 也是出作用域，析构里那句 fclose 跑了，格子外面那行轮不到

